console.log(`Page 1 has ${p1.length} products:`);
for (const p of p1) {
  console.log(`- [${p.reviewCount} reviews, $${p.minPrice}${p.maxPrice !== p.minPrice ? '-$' + p.maxPrice : ''}] ${p.title} (${p.href})`);
}

