const tabId = 343605502;
const productsData = await browserjs(tabId, () => {
  // Find all product cards or items
  // Let's inspect the main content area
  const main = document.querySelector('main') || document.body;

  // Find all product cards
  // Let's inspect elements containing price
  const cards = [];
  const links = Array.from(main.querySelectorAll('a[href*="/shop/"]'));
  const seenUrls = new Set();

  for (const link of links) {
    const href = link.href;
    if (seenUrls.has(href) || href.includes('/category/')) continue;

    // Find the enclosing card container
    let container = link;
    for (let i = 0; i < 6; i++) {
      if (!container.parentElement || container.tagName === 'MAIN') break;
      container = container.parentElement;
      if (container.querySelector('[aria-label*="rating"], [class*="rating"], [data-testid*="star"]')) {
        break;
      }
    }

    const text = container.innerText;
    // Check if it looks like a product card (has price or rating or buy button)
    if (text.includes('$') || text.includes('stars') || text.includes('reviews')) {
      seenUrls.add(href);
      cards.push({
        href,
        linkText: link.textContent?.trim(),
        fullText: text
      });
    }
  }

  return {
    totalFound: cards.length,
    cards: cards.map(c => ({
      href: c.href,
      title: c.linkText,
      snippet: c.fullText.replace(/\n+/g, ' | ').slice(0, 300)
    }))
  };
});

console.log("Products found:", productsData.totalFound);
console.log(JSON.stringify(productsData.cards.slice(0, 10), null, 2));

