const tabId = 343605502;
const page1Products = await browserjs(tabId, () => {
  // Find product cards
  // In CVS search results, each product typically has a product link with prodid
  const links = Array.from(document.querySelectorAll('a[href*="-prodid-"]'));
  const uniqueProducts = new Map();

  for (const link of links) {
    const href = link.href.split('?')[0]; // strip query
    if (uniqueProducts.has(href)) continue;

    // Find the enclosing product card
    let el = link;
    while (el && el.parentElement && !el.getAttribute('data-testid')?.includes('product') && el.tagName !== 'LI' && !el.className.includes('css-')) {
      if (el.parentElement.tagName === 'MAIN') break;
      el = el.parentElement;
    }
    // Alternatively walk up to find a container with price and rating
    let card = link;
    while (card && card.parentElement && card.parentElement.tagName !== 'MAIN') {
      const txt = card.innerText || '';
      if (txt.includes('$') && (txt.includes('reviews') || /\b\d+\b/.test(txt))) {
        // check if parent contains more than one product link
        if (card.parentElement.querySelectorAll('a[href*="-prodid-"]').length > 3) {
          break;
        }
      }
      card = card.parentElement;
    }

    // Let's get the card's inner text or structured elements
    // Typically the title link has text or an aria-label
    let title = link.textContent?.trim();
    if (!title || title.length < 3) {
      // Find title inside card
      const heading = card.querySelector('h2, h3, [class*="title"], [data-testid*="title"]');
      if (heading) title = heading.textContent?.trim();
    }

    // Extract price
    const cardText = card.innerText;
    const priceMatch = cardText.match(/\$(\d+\.\d{2})/);
    const price = priceMatch ? parseFloat(priceMatch[1]) : null;

    // Extract review count
    // Often there's a link with reviews or aria-label with "customer reviews"
    const reviewLink = card.querySelector('a[href*="-reviews"], [aria-label*="customer reviews"]');
    let reviews = null;
    if (reviewLink) {
      const match = reviewLink.getAttribute('aria-label')?.match(/(\d+)\s+customer reviews/) || reviewLink.textContent?.match(/(\d+)/);
      if (match) reviews = parseInt(match[1], 10);
    }

    uniqueProducts.set(href, {
      title,
      href,
      price,
      reviews,
      rawText: cardText.replace(/\n+/g, ' | ').slice(0, 200)
    });
  }

  return Array.from(uniqueProducts.values());
});

console.log("Page 1 products count:", page1Products.length);
console.log(JSON.stringify(page1Products, null, 2));

