const tabId = 343605502;
// Let's get the exact list of unique products on Page 1
const getProducts = () => {
  const cards = Array.from(document.querySelectorAll('a[href*="-prodid-"]'));
  const prods = new Map();
  for (const a of cards) {
    let href = a.href.split('?')[0];
    if (href.endsWith('-reviews')) {
      href = href.replace('-reviews', '');
    }
    if (prods.has(href)) continue;

    // Find card container
    let card = a;
    while (card && card.parentElement && card.parentElement.tagName !== 'MAIN') {
      if (card.parentElement.querySelectorAll('a[href*="-prodid-"]').length > 4) break;
      card = card.parentElement;
    }

    const cardText = card.innerText;
    // Extract title: often a link text
    const titleLink = card.querySelector('a[href*="-prodid-"]:not([href*="-reviews"])');
    const title = titleLink?.textContent?.trim() || a.textContent?.trim();

    // Extract price: look for $XX.XX
    const prices = Array.from(cardText.matchAll(/\$(\d+\.\d{2})/g)).map(m => parseFloat(m[1]));

    // Extract review count
    // Look for e.g. "This product has 282 customer reviews" or text
    const revEl = card.querySelector('[aria-label*="customer reviews"]');
    let reviewCount = null;
    if (revEl) {
      const m = revEl.getAttribute('aria-label')?.match(/(\d+)\s+customer reviews/);
      if (m) reviewCount = parseInt(m[1], 10);
    }
    if (reviewCount === null) {
      // Look in text for isolated number near stars
      const m = cardText.match(/\|\s*(\d{1,5})\s*\|\s*\$/);
      if (m) reviewCount = parseInt(m[1], 10);
    }

    prods.set(href, {
      title,
      href,
      prices,
      minPrice: prices.length ? Math.min(...prices) : null,
      maxPrice: prices.length ? Math.max(...prices) : null,
      reviewCount,
      rawSnippet: cardText.replace(/\n+/g, ' | ').slice(0, 150)
    });
  }
  return Array.from(prods.values());
};

const p1 = await browserjs(tabId, getProducts);
console.log(`Page 1 has ${p1.length} products:`);
for (const p of p1) {
  console.log(`- [${p.reviewCount} reviews, $${p.minPrice}${p.maxPrice !== p.minPrice ? '-$' + p.maxPrice : ''}] ${p.title} (${p.href})`);
}

