const tabId = 343605502;
const cardData = await browserjs(tabId, () => {
  // Let's find all product cards by looking for the container of each prodid link
  // Let's see all links with -prodid-
  const links = Array.from(document.querySelectorAll('a[href*="-prodid-"]:not([href*="-reviews"])'));
  const results = [];
  const seen = new Set();

  for (const a of links) {
    const href = a.href.split('?')[0];
    if (seen.has(href)) continue;
    seen.add(href);

    // Let's find the card container. In modern CVS web, cards might be in a list or div grid
    let card = a;
    while (card.parentElement && card.parentElement.tagName !== 'MAIN') {
      // Check if parent has multiple product links
      if (card.parentElement.querySelectorAll('a[href*="-prodid-"]:not([href*="-reviews"])').length > 1) {
        break;
      }
      card = card.parentElement;
    }

    // Now inside this card:
    const title = a.textContent?.trim();
    // Price
    const priceEl = card.querySelector('[data-testid*="price"], [class*="price"]') || card;
    const priceText = priceEl.innerText;

    // Reviews
    const revEl = card.querySelector('[aria-label*="customer reviews"]');
    const revLabel = revEl?.getAttribute('aria-label');
    const revText = revEl?.textContent?.trim();

    results.push({
      title,
      href,
      revLabel,
      revText,
      cardText: card.innerText.replace(/\n+/g, ' | ').slice(0, 200)
    });
  }
  return results;
});

console.log(`Found ${cardData.length} cards on page 1:`);
for (const c of cardData) {
  console.log(`Title: ${c.title} | Rev: ${c.revLabel || c.revText} | URL: ${c.href}`);
}

