const prodsToCheck = [
  { sku: "448404", name: "Men 50+ Advanced Tablets 65ct", url: "https://www.cvs.com/shop/cvs-men-50-advanced-multivitamin-tablets-65-ct-prodid-448404" },
  { sku: "378615", name: "Women's Tablets 120ct", url: "https://www.cvs.com/shop/cvs-women-s-multivitamin-tablets-120-ct-prodid-378615" },
  { sku: "378592", name: "Men's Tablets 120ct", url: "https://www.cvs.com/shop/cvs-men-s-multivitamin-tablets-120-ct-prodid-378592" },
  { sku: "448393", name: "Women's 50+ Advanced Tablets 65ct", url: "https://www.cvs.com/shop/cvs-women-s-50-advanced-multivitamin-tablets-prodid-7201294" },
  { sku: "255042", name: "Women's Tablets 100ct", url: "https://www.cvs.com/shop/cvs-women-s-multivitamin-tablets-100-ct-prodid-255042" },
  { sku: "689762", name: "Spectravite Women's 50+ Tablets 100ct", url: "https://www.cvs.com/shop/cvs-spectravite-women-s-50-multivitamin-tablets-100-ct-prodid-689762" },
  { sku: "285908", name: "Women's Multivitamin Gummies 70ct", url: "https://www.cvs.com/shop/cvs-women-s-multivitamin-gummies-70-ct-prodid-1170367" }
];

const checkDetails = await browserjs(tabId, async (list) => {
  const output = [];
  for (const item of list) {
    try {
      const res = await fetch(item.url);
      const html = await res.text();

      // Let's parse JSON objects in the page
      // Often Redux or Apollo or Next state has product data
      // Look for "specifications" or "concern" or "dietary"
      const concernMatch = html.match(/"concern":\s*(\[[^\]]+\])/);
      const ingredientPref = html.match(/"ingredientPreference":\s*(\[[^\]]+\])/);
      const allergenFree = html.match(/"allergenFree":\s*(\[[^\]]+\])/);
      const dietaryPref = html.match(/"dietaryPreference":\s*(\[[^\]]+\])/);
      const detailsParagraph = html.match(/"detailsParagraph":\s*("[^"]+")/);

      // Also search raw text for gluten, wheat, celiac
      const glutenMatches = Array.from(html.matchAll(/([^\n<>"{}]{0,50}(?:gluten|wheat|celiac|free of|no artificial)[^\n<>"{}]{0,50})/gi)).map(m => m[0].trim());

      output.push({
        sku: item.sku,
        name: item.name,
        concern: concernMatch ? concernMatch[1] : null,
        ingredientPref: ingredientPref ? ingredientPref[1] : null,
        allergenFree: allergenFree ? allergenFree[1] : null,
        dietaryPref: dietaryPref ? dietaryPref[1] : null,
        glutenMatches: [...new Set(glutenMatches)].slice(0, 10)
      });
    } catch (e) {
      output.push({ sku: item.sku, name: item.name, error: e.message });
    }
  }
  return output;
}, prodsToCheck);

console.log(JSON.stringify(checkDetails, null, 2));

