    let container = h.parentElement;
    for (let i = 0; i < 4; i++) {
      if (container.nextElementSibling) {
        return container.nextElementSibling.innerText || container.innerText;
      }
      container = container.parentElement;
    }
    return container?.innerText;
  };

  return {
