      const price = priceMatch ? parseFloat(priceMatch[1]) : null;

      // Check gluten mentions
      const glutenSnippets = Array.from(html.matchAll(/([^\\]{0,50}gluten[^\\]{0,50})/gi)).map(m => m[0].trim());

