const tabId = 343605502;
const priceElements = await browserjs(tabId, () => {
  // Look for any elements containing numbers or $ in the product summary area
  const main = document.querySelector('main');
  const allElements = Array.from(main.querySelectorAll('*'));
  const found = [];
  for (const el of allElements) {
    if (el.children.length === 0 && (el.textContent.includes('$') || /^\d+\.\d{2}$/.test(el.textContent.trim()))) {
      found.push({
        tag: el.tagName,
        text: el.textContent.trim(),
        parentClass: el.parentElement?.className
      });
    }
  }
  return found;
});
console.log("Price elements:", priceElements);

